import{_ as r,I as s,c as n,o,ag as a,J as i}from"./chunks/framework.Vyheyqg9.js";const b=JSON.parse('{"title":"S3 and CloudFront: storage and frontend delivery","description":"","frontmatter":{},"headers":[],"relativePath":"aws/storage-and-frontend.md","filePath":"aws/storage-and-frontend.md"}'),c={name:"aws/storage-and-frontend.md"};function d(l,e,h,p,m,g){const t=s("MermaidDiagram");return o(),n("div",null,[e[0]||(e[0]=a('<h1 id="s3-and-cloudfront-storage-and-frontend-delivery" tabindex="-1">S3 and CloudFront: storage and frontend delivery <a class="header-anchor" href="#s3-and-cloudfront-storage-and-frontend-delivery" aria-label="Permalink to “S3 and CloudFront: storage and frontend delivery”">​</a></h1><p>S3 stores objects. CloudFront delivers cached content through a CDN. Together they can serve a browser application without running a dedicated web server for its static files.</p><h2 id="choose-the-right-storage-model" tabindex="-1"><span class="hub-section-number">1 </span>Choose the right storage model <a class="header-anchor" href="#choose-the-right-storage-model" aria-label="Permalink to “1 Choose the right storage model”">​</a></h2><table tabindex="0"><thead><tr><th>Model</th><th>How an application sees it</th><th>Typical AWS service</th></tr></thead><tbody><tr><td>Object</td><td>Retrieve or replace a value by key through an API</td><td>S3</td></tr><tr><td>Block</td><td>Disk blocks exposed to an operating system</td><td>EBS</td></tr><tr><td>File</td><td>A shared filesystem with paths and filesystem operations</td><td>EFS</td></tr></tbody></table><p>An S3 object consists of content, a key and metadata; versioning can add a version ID. <code>images/product-1.jpg</code> is an object key whose prefix looks like a directory. In general purpose buckets this is not a normal filesystem directory. A bucket has a Region even though S3 is accessed through a global service brand.</p><h2 id="versioning-lifecycle-and-consistency" tabindex="-1"><span class="hub-section-number">2 </span>Versioning, lifecycle and consistency <a class="header-anchor" href="#versioning-lifecycle-and-consistency" aria-label="Permalink to “2 Versioning, lifecycle and consistency”">​</a></h2><p>Versioning preserves object versions; deleting a current object can create a delete marker. Older versions can still occupy storage and incur charges. Lifecycle rules can expire objects or transition them between storage classes. Their effects depend on which versions and prefixes the rules cover.</p><p>S3 provides strong read-after-write consistency for object writes, overwrites and deletes. The supplied older S3 slides&#39; claim that overwrites and deletes are eventually consistent is outdated. CloudFront can still serve an older cached representation independently of S3&#39;s consistency. <a href="https://docs.aws.amazon.com/AmazonS3/latest/userguide/Welcome.html" target="_blank" rel="noreferrer">S3 data model and consistency</a>.</p><p>Choose storage classes using access frequency, required retrieval latency, resilience scope and total cost. Standard, Intelligent-Tiering, infrequent-access and Glacier classes solve different problems. Retrieval fees, minimum storage duration and monitoring charges can matter as much as the storage price. Use current class documentation rather than an old slide&#39;s price or limit.</p><h2 id="private-assets-behind-a-public-delivery-endpoint" tabindex="-1"><span class="hub-section-number">3 </span>Private assets behind a public delivery endpoint <a class="header-anchor" href="#private-assets-behind-a-public-delivery-endpoint" aria-label="Permalink to “3 Private assets behind a public delivery endpoint”">​</a></h2>',10)),i(t,{"encoded-source":"flowchart%20LR%0A%20%20%20%20Viewer%5BViewer%5D%20--%3E%7CHTTPS%7C%20CDN%5BCloudFront%20distribution%5D%0A%20%20%20%20CDN%20--%3E%7CSigned%20origin%20request%7C%20Bucket%5BPrivate%20S3%20bucket%5D"}),e[1]||(e[1]=a('<p>A distribution identifies origins and cache behaviors. A behavior can select an origin by path and control methods, cache policy and viewer protocol handling. For a private S3 origin, use <strong>Origin Access Control (OAC)</strong> and the corresponding bucket policy. OAI appears in older material; AWS recommends OAC for new designs. An S3 <strong>website endpoint</strong> is a custom origin and cannot use OAC. <a href="https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/private-content-restricting-access-to-s3.html" target="_blank" rel="noreferrer">CloudFront origin access</a>.</p><p>S3 website hosting is a separate mechanism from using a private S3 REST origin. The former does not provide HTTPS directly at the website endpoint. Managed hosting such as Amplify is another option when a simpler deployment workflow is preferable. <a href="https://docs.aws.amazon.com/AmazonS3/latest/userguide/WebsiteHosting.html" target="_blank" rel="noreferrer">AWS static hosting overview</a>.</p><h2 id="cache-keys-and-deployment-behavior" tabindex="-1"><span class="hub-section-number">4 </span>Cache keys and deployment behavior <a class="header-anchor" href="#cache-keys-and-deployment-behavior" aria-label="Permalink to “4 Cache keys and deployment behavior”">​</a></h2><p>A cache key decides which requests may reuse a response. If a response varies by a parameter that the cache ignores, different callers may receive an inappropriate response. If every request has a unique cache key, cache reuse disappears.</p><p>A TTL controls how long cached content can remain fresh. Invalidations remove selected cached paths; they are distinct from uploading new objects. Content-hashed assets such as <code>app.a1b2.js</code> can have long cache lifetimes, while the HTML entry point needs a strategy that allows it to reference the latest assets.</p><p>For an SPA, opening <code>/products/123</code> directly needs a deliberate route fallback. Returning <code>index.html</code> for every error can hide missing images, broken JavaScript paths and permission errors. Separate navigation fallback from genuine asset and API failures.</p><h2 id="cors-does-not-grant-access" tabindex="-1"><span class="hub-section-number">5 </span>CORS does not grant access <a class="header-anchor" href="#cors-does-not-grant-access" aria-label="Permalink to “5 CORS does not grant access”">​</a></h2><p>CORS tells browsers which cross-origin responses scripts may read. It does not replace IAM, bucket policy or application authorization. A command-line client is not constrained by browser CORS enforcement. Configure browser origins and headers for the actual application instead of treating <code>*</code> as a security fix.</p><p>For temporary upload access, see <a href="./file-imports.html">file imports</a>. For SQL and records, see <a href="./databases.html">databases</a>.</p>',9))])}const f=r(c,[["render",d]]);export{b as __pageData,f as default};
